mapper.select:
select count(1)
from ygb_worker_activity_join
where del_flag = '0'
  and activity_key = #{activityKey}
  and user_id = #{userId}

mapper.insert:
insert into ygb_worker_activity_join (
    activity_key, user_id, person_id, person_name, mobile, status, remark, create_by, create_time, del_flag
) values (
    #{activityKey}, #{userId}, #{personId}, #{personName}, #{mobile}, #{status}, #{remark}, #{createBy}, sysdate(), '0'
)

insert into ygb_worker_video_progress (
    video_key, user_id, person_id, watched_seconds, total_seconds, completed_flag, create_time, del_flag
) values (
    #{videoKey}, #{userId}, #{personId}, #{watchedSeconds}, #{totalSeconds}, #{completedFlag}, sysdate(), '0'
)
